import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independently strip only the five-op admission ports, compare every original method and archive entry. */
public final class SelectedPlayerIntentDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",F=P+"ForcedCombat",H=P+"NativeSelectedPlayerIntent";
 static void need(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){
  var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var other=jar.getJarEntry(e.getName());need(other!=null,"no removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(other).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());need(changed.equals(Set.of(PC+".class",F+".class"))&&fresh.equals(Set.of(H+".class")),"exact archive boundary");int count=0;
  for(String name:List.of(PC,F)){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(old.fields.size()==now.fields.size()&&now.methods.size()==old.methods.size()+(name.equals(F)?1:0),"bounded schema");for(int i=0;i<old.fields.size();i++){var f=old.fields.get(i);var g=now.fields.get(i);need(f.access==g.access&&f.name.equals(g.name)&&f.desc.equals(g.desc)&&Objects.equals(f.value,g.value),"existing fields unchanged");}
   for(var previous:old.methods){var m=now.methods.stream().filter(x->x.name.equals(previous.name)&&x.desc.equals(previous.desc)).findFirst().orElseThrow();need(m.access==previous.access,"same method access");for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)){
    need(name.equals(PC)&&Set.of("object","attack").contains(call.name)&&(m.desc.startsWith("([B")||m.desc.startsWith("(L"+P+"Protocol$"))&&m.desc.contains(P+"BattleSpellCatalog$")&&m.desc.endsWith(")V"),"typed spell method only");var load=FreezeAcceptedMethods.prev(n);var pc=FreezeAcceptedMethods.prev(load);var store=FreezeAcceptedMethods.prev(pc);var parse=store==null?null:FreezeAcceptedMethods.prev(store);var branch=FreezeAcceptedMethods.next(n);var ret=FreezeAcceptedMethods.next(branch);
    need(pc instanceof VarInsnNode p&&p.getOpcode()==ALOAD&&p.var==0&&load instanceof VarInsnNode l&&l.getOpcode()==ALOAD,"exact PC and decoded target loads");boolean argument=m.desc.startsWith("(L"+P+"Protocol$");if(argument)need(store==null&&((VarInsnNode)load).var==1,"same original decoded first argument");else need(store instanceof VarInsnNode s&&s.getOpcode()==ASTORE&&s.var==((VarInsnNode)load).var&&parse instanceof MethodInsnNode q&&q.owner.equals(P+"Protocol")&&q.name.equals(call.name.equals("object")?"objectSpellRequest":"attackSpellRequest"),"exact decoded original target, no packet replacement");need(branch instanceof JumpInsnNode j&&j.getOpcode()==IFNE&&ret.getOpcode()==RETURN&&FreezeAcceptedMethods.next(ret)==FreezeAcceptedMethods.next(j.label),"only denied return, same original continuation");for(var x:List.of(pc,load,n,branch,ret))m.instructions.remove(x);count++;
   }need(Arrays.equals(FreezeSourceTargetDelta.body(old,previous,previous.name,previous.access),FreezeSourceTargetDelta.body(now,m,previous.name,previous.access)),"all original numerical/cost/life methods inverse "+m.name);}
   if(name.equals(F)){var read=now.methods.stream().filter(x->x.name.equals("nativeSelectedObjectIntent")).findFirst().orElseThrow();need(read.access==ACC_STATIC&&read.desc.equals("(L"+PC+";J)Z"),"one static authority reader");for(var n:read.instructions){need(n.getOpcode()!=PUTFIELD&&n.getOpcode()!=PUTSTATIC&&n.getOpcode()!=NEW,"reader never stores authority");if(n instanceof MethodInsnNode call)need(Set.of("get","attacker","target").contains(call.name),"reader only original scoped intent fields");}}
  }need(count>=50,"targeted parser coverage="+count);var helper=FreezeSourceTargetDelta.read(jar,H);need(helper.fields.isEmpty(),"no helper state/registry/TLS");for(var m:helper.methods)for(var n:m.instructions){need(n.getOpcode()!=PUTFIELD&&n.getOpcode()!=PUTSTATIC&&n.getOpcode()!=MONITORENTER,"no authority or actor mutation/monitor");if(n instanceof MethodInsnNode c)need(!c.owner.startsWith("java/sql/")&&!c.owner.startsWith("java/nio/file/")&&!Set.of("set","remove","activate","admit","commit","lock","tryLock").contains(c.name),"read-only selected-PC policy");}
  System.out.println("PASS independent archive/schema/all-method inverse; selected-PC parser ports="+count+"; no original authority mutation");
 }}
}
